public class ImportListBuilderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.List<String> messy = java.util.Arrays.asList(
                "java.util.List", "java.awt.List", "java.lang.String", "com.app.Helper",
                "java.util.Map", "java.util.List", "Untyped");
        java.util.List<String> tidy = java.util.Arrays.asList("java.util.Map", "java.io.File");
        java.util.List<String> freeOnly = java.util.Arrays.asList(
                "java.lang.Integer", "com.app.Widget", "Untyped");

        check("clash resolved alphabetically", "[import java.awt.List;, import java.util.Map;]",
                ImportListBuilder.importLines("com.app", messy).toString());
        check("loser must be qualified", "[java.util.List]",
                ImportListBuilder.mustQualify("com.app", messy).toString());
        check("plain sorted imports", "[import java.io.File;, import java.util.Map;]",
                ImportListBuilder.importLines("com.app", tidy).toString());
        check("nothing to qualify", "[]",
                ImportListBuilder.mustQualify("com.app", tidy).toString());
        check("free types need no imports", "[]",
                ImportListBuilder.importLines("com.app", freeOnly).toString());
        check("duplicates counted once", "[import java.util.Map;]",
                ImportListBuilder.importLines("com.app", java.util.Arrays.asList("java.util.Map", "java.util.Map")).toString());
        check("null list", "[]", ImportListBuilder.importLines("com.app", null).toString());
        check("null list for mustQualify", "[]",
                ImportListBuilder.mustQualify("com.app", null).toString());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

