public class ImportListBuilder {

    public static java.util.List<String> importLines(String currentPackage, java.util.List<String> names) {
        java.util.List<String> lines = new java.util.ArrayList<>();
        for (String winner : winners(currentPackage, names)) {
            lines.add("import " + winner + ";");
        }
        return lines;
    }

    public static java.util.List<String> mustQualify(String currentPackage, java.util.List<String> names) {
        java.util.List<String> losers = new java.util.ArrayList<>(needed(currentPackage, names));
        losers.removeAll(winners(currentPackage, names));
        return losers;
    }

    private static java.util.List<String> winners(String currentPackage, java.util.List<String> names) {
        java.util.Set<String> claimed = new java.util.HashSet<>();
        java.util.List<String> winners = new java.util.ArrayList<>();
        for (String name : needed(currentPackage, names)) {
            String simpleName = name.substring(name.lastIndexOf('.') + 1);
            if (claimed.add(simpleName)) {
                winners.add(name);
            }
        }
        return winners;
    }

    private static java.util.List<String> needed(String currentPackage, java.util.List<String> names) {
        java.util.Set<String> kept = new java.util.TreeSet<>();
        if (names == null) {
            return new java.util.ArrayList<>();
        }
        String here = currentPackage == null ? "" : currentPackage;
        for (String name : names) {
            if (name == null) {
                continue;
            }
            int lastDot = name.lastIndexOf('.');
            if (lastDot < 0) {
                continue;
            }
            String owner = name.substring(0, lastDot);
            if (owner.equals(here) || owner.equals("java.lang")) {
                continue;
            }
            kept.add(name);
        }
        return new java.util.ArrayList<>(kept);
    }
}
